import org.apache.nifi.processor.io.*
import java.nio.file.*
import java.nio.charset.StandardCharsets

def flowFile = session.get()
if (!flowFile) return

try {
    def destPath = Paths.get(
        context.getProperty("Destination File")
               .evaluateAttributeExpressions(flowFile)
               .getValue()
    )
    def destParent = destPath.getParent()
    def md5checksum = context.getProperty("Flowfile Checksum Attribute")
                             .evaluateAttributeExpressions(flowFile)
                             .getValue()

    flowFile = session.putAttribute(
        flowFile, "writeChecksumToFile.destinationPath", destPath.toString()
    )

    if (md5checksum == null) {
        throw new IllegalArgumentException("Missing attribute on flowfile: eosipProduct.md5checksum")
    }

    if (destParent != null && !Files.isDirectory(destParent)) {
        throw new NoSuchFileException("Destination directory does not exist: " + destParent.toString())
    }

    // Write checksum to file (overwrite)
    Files.write(destPath, md5checksum.getBytes(StandardCharsets.UTF_8), StandardOpenOption.CREATE_NEW)

    // Success path
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    // Attach informative error info to FlowFile
    flowFile = session.putAttribute(
        flowFile, "writeChecksumToFile.error",
        e.getClass().getName() + ": " + e.getMessage()
    )
    session.transfer(flowFile, REL_FAILURE)
}

